begin;
create table if not exists public.telecom_sadad_posting_accounts(id uuid primary key default gen_random_uuid(),provider text not null check(provider in('mobily','stc')),branch_id bigint not null references public.branches(id),ledger_id bigint not null,ledger_code text,ledger_name text not null,created_by uuid not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,branch_id));
create table if not exists public.telecom_sadad_subscribers(id uuid primary key default gen_random_uuid(),provider text not null check(provider in('mobily','stc')),subscriber_number text not null check(subscriber_number~'^[0-9]+$'),branch_id bigint not null references public.branches(id),created_by uuid not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,subscriber_number));
alter table public.telecom_sadad_posting_accounts enable row level security;
alter table public.telecom_sadad_subscribers enable row level security;
revoke all on public.telecom_sadad_posting_accounts,public.telecom_sadad_subscribers from public,anon,authenticated;
grant all on public.telecom_sadad_posting_accounts,public.telecom_sadad_subscribers to service_role;

create or replace function public.get_telecom_sadad_configuration() returns jsonb language plpgsql stable security definer set search_path=public as $$ declare v_actor uuid:=public.aqura_current_user_id(); begin if not public.statements_manager_can_access(v_actor) then raise exception 'Statements Manager permission required.'; end if; return jsonb_build_object('posting_accounts',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('branch_name',coalesce(b.name_en,b.name_ar),'branch_location',coalesce(b.location_en,b.location_ar,'')) order by p.provider,b.name_en) from public.telecom_sadad_posting_accounts p join public.branches b on b.id=p.branch_id),'[]'::jsonb),'subscribers',coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('branch_name',coalesce(b.name_en,b.name_ar),'branch_location',coalesce(b.location_en,b.location_ar,'')) order by s.provider,s.subscriber_number) from public.telecom_sadad_subscribers s join public.branches b on b.id=s.branch_id),'[]'::jsonb)); end $$;
create or replace function public.save_telecom_sadad_posting_account(p_provider text,p_branch_id bigint,p_ledger_id bigint,p_ledger_code text,p_ledger_name text) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=public.aqura_current_user_id(); begin if not public.statements_manager_can_access(v_actor) then raise exception 'Statements Manager permission required.'; end if; insert into public.telecom_sadad_posting_accounts(provider,branch_id,ledger_id,ledger_code,ledger_name,created_by) values(lower(p_provider),p_branch_id,p_ledger_id,nullif(btrim(p_ledger_code),''),btrim(p_ledger_name),v_actor) on conflict(provider,branch_id) do update set ledger_id=excluded.ledger_id,ledger_code=excluded.ledger_code,ledger_name=excluded.ledger_name,updated_at=now(); end $$;
create or replace function public.save_telecom_sadad_subscriber(p_provider text,p_subscriber_number text,p_branch_id bigint) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=public.aqura_current_user_id(); v_number text:=regexp_replace(coalesce(p_subscriber_number,''),'\D','','g'); begin if not public.statements_manager_can_access(v_actor) then raise exception 'Statements Manager permission required.'; end if; insert into public.telecom_sadad_subscribers(provider,subscriber_number,branch_id,created_by) values(lower(p_provider),v_number,p_branch_id,v_actor) on conflict(provider,subscriber_number) do update set branch_id=excluded.branch_id,updated_at=now(); end $$;
create or replace function public.get_telecom_statement_tasks() returns jsonb language plpgsql stable security definer set search_path=public as $$ declare v_actor uuid:=public.aqura_current_user_id(); begin if not public.statements_manager_can_access(v_actor) then raise exception 'Statements Manager permission required.'; end if; return coalesce((select jsonb_agg(jsonb_build_object('statement_mjv_id',m.id,'statement_date',m.statement_date,'bank',m.bank,'mjv_type',m.mjv_type,'branch_tasks',coalesce(x.items,'[]'::jsonb)) order by m.statement_date desc) from public.statement_mjvs m left join lateral(select jsonb_agg(jsonb_build_object('branch_name',b.branch_name,'task_status',b.task_status,'assigned_user_name',coalesce(e.name_en,e.name_ar,u.username,'Not assigned'),'debit_total',b.debit_total,'credit_total',b.credit_total)) items from public.statement_mjv_branches b left join public.assistant_workflow_tasks t on t.id=b.task_id left join public.hr_employee_master e on e.user_id=t.assigned_to and e.is_removed=false left join public.users u on u.id=t.assigned_to where b.statement_mjv_id=m.id)x on true where m.mjv_type in('mobily','stc') and m.status<>'completed'),'[]'::jsonb); end $$;
revoke all on function public.get_telecom_sadad_configuration(),public.save_telecom_sadad_posting_account(text,bigint,bigint,text,text),public.save_telecom_sadad_subscriber(text,text,bigint),public.get_telecom_statement_tasks() from public,anon;
grant execute on function public.get_telecom_sadad_configuration(),public.save_telecom_sadad_posting_account(text,bigint,bigint,text,text),public.save_telecom_sadad_subscriber(text,text,bigint),public.get_telecom_statement_tasks() to authenticated;
notify pgrst,'reload schema';
commit;
